import{_ as l,a0 as r,w as p,s as o,I as e,x as n,a1 as s,A as i,ao as c}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"Rancher：一個全面的可用於產品環境的容器管理平台 | LCTT x X-CMD","titleTemplate":false,"description":"Rancher：一個全面的可用於產品環境的容器管理平台 | LCTT (201904) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Rancher：一個全面的可用於產品環境的容器管理平台 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Rancher：一個全面的可用於產品環境的容器管理平台 | LCTT (201904) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201904/20180205 Rancher - Container Management Application","title":"Rancher：一個全面的可用於產品環境的容器管理平台","tag":"201904","desc":""},"relativePath":"201904/20180205 Rancher - Container Management Application.md","filePath":"[post].md"}'),d={name:"201904/20180205 Rancher - Container Management Application.md"};function h(g,a,u,m,k,w){const t=r("Link");return p(),o("div",null,[a[22]||(a[22]=e("h1",{id:"rancher-一個全面的可用於產品環境的容器管理平台",tabindex:"-1"},[n("Rancher：一個全面的可用於產品環境的容器管理平台 "),e("a",{class:"header-anchor",href:"#rancher-一個全面的可用於產品環境的容器管理平台","aria-label":"Permalink to “Rancher：一個全面的可用於產品環境的容器管理平台”"},"​")],-1)),a[23]||(a[23]=e("p",null,"Docker 作為一款容器化應用的新興軟件，被大多數 IT 公司使用來減少基礎設施平台的成本。",-1)),a[24]||(a[24]=e("p",null,"通常，沒有 GUI 的 Docker 軟件對於 Linux 管理員來説很容易，但是對於開發者來就有點困難。當把它搬到生產環境上來，那麼它對 Linux 管理員來説也相當不友好。那麼，輕鬆管理 Docker 的最佳解決方案是什麼呢？",-1)),a[25]||(a[25]=e("p",null,"唯一的辦法就是提供 GUI。Docker API 允許第三方應用接入 Docker。在市場上有許多 Docker GUI 應用。我們已經寫過一篇關於 Portainer 應用的文章。今天我們來討論另一個應用，Rancher。",-1)),a[26]||(a[26]=e("p",null,"容器讓軟件開發更容易，讓開發者更快的寫代碼、更好的運行它們。但是，在生產環境上運行容器卻很困難。",-1)),e("p",null,[a[1]||(a[1]=e("strong",null,"推薦閲讀：",-1)),a[2]||(a[2]=n()),s(t,{href:"https://www.2daygeek.com/portainer-a-simple-docker-management-gui/"},{default:i(()=>[...a[0]||(a[0]=[n("Portainer：一個簡單的 Docker 管理圖形工具",-1)])]),_:1})]),a[27]||(a[27]=e("h3",{id:"rancher-簡介",tabindex:"-1"},[n("Rancher 簡介 "),e("a",{class:"header-anchor",href:"#rancher-簡介","aria-label":"Permalink to “Rancher 簡介”"},"​")],-1)),e("p",null,[s(t,{href:"http://rancher.com/"},{default:i(()=>[...a[3]||(a[3]=[n("Rancher",-1)])]),_:1}),a[4]||(a[4]=n(" 是一個全面的容器管理平台，它可以讓容器在各種基礎設施平台的生產環境上部署和運行更容易。它提供了諸如多主機網絡、全局/本地負載均衡和卷快照等基礎設施服務。它整合了原生 Docker 的管理能力，如 Docker Machine 和 Docker Swarm。它提供了豐富的用户體驗，讓 DevOps 管理員在更大規模的生產環境上運行 Docker。",-1))]),a[28]||(a[28]=e("p",null,"訪問以下文章可以瞭解 Linux 系統上安裝 Docker。",-1)),a[29]||(a[29]=e("p",null,[e("strong",null,"推薦閲讀：")],-1)),e("ul",null,[e("li",null,[s(t,{href:"https://www.2daygeek.com/install-docker-on-centos-rhel-fedora-ubuntu-debian-oracle-archi-scentific-linux-mint-opensuse/"},{default:i(()=>[...a[5]||(a[5]=[n("如何在 Linux 上安裝 Docker",-1)])]),_:1})]),e("li",null,[s(t,{href:"https://www.2daygeek.com/list-search-pull-download-remove-docker-images-on-linux/"},{default:i(()=>[...a[6]||(a[6]=[n("如何在 Linux 上使用 Docker 鏡像",-1)])]),_:1})]),e("li",null,[s(t,{href:"https://www.2daygeek.com/create-run-list-start-stop-attach-delete-interactive-daemonized-docker-containers-on-linux/"},{default:i(()=>[...a[7]||(a[7]=[n("如何在 Linux 上使用 Docker 容器",-1)])]),_:1})]),e("li",null,[s(t,{href:"https://www.2daygeek.com/install-run-applications-inside-docker-containers/"},{default:i(()=>[...a[8]||(a[8]=[n("如何在 Docker 容器內安裝和運行應用",-1)])]),_:1})])]),a[30]||(a[30]=c(`<h3 id="rancher-特性" tabindex="-1">Rancher 特性 <a class="header-anchor" href="#rancher-特性" aria-label="Permalink to “Rancher 特性”">​</a></h3><ul><li>可以在兩分鐘內安裝 Kubernetes。</li><li>一鍵啓動應用（90 個流行的 Docker 應用）。</li><li>部署和管理 Docker 更容易。</li><li>全面的生產級容器管理平台。</li><li>可以在生產環境上快速部署容器。</li><li>強大的自動部署和運營容器技術。</li><li>模組化基礎設施服務。</li><li>豐富的編排工具。</li><li>Rancher 支持多種認證機制。</li></ul><h3 id="怎樣安裝-rancher" tabindex="-1">怎樣安裝 Rancher <a class="header-anchor" href="#怎樣安裝-rancher" aria-label="Permalink to “怎樣安裝 Rancher”">​</a></h3><p>由於 Rancher 是以輕量級的 Docker 容器方式運行，所以它的安裝非常簡單。Rancher 是由一組 Docker 容器部署的。只需要簡單的啓動兩個容器就能運行 Rancher。一個容器用作管理服務器，另一個容器在各個節點上作為代理。在 Linux 系統下簡單的運行下列命令就能部署 Rancher。</p><p>Rancher 服務器提供了兩個不同的安裝包標籤如 <code>stable</code> 和 <code>latest</code>。下列命令將會拉取適合的 Rancher 鏡像並安裝到你的操作系統上。Rancher 服務器僅需要兩分鐘就可以啓動。</p><ul><li><code>latest</code>：這個標籤是他們的最新開發構建。這些構建將通過 Rancher CI 的自動化框架進行驗證，不建議在生產環境使用。</li><li><code>stable</code>：這是最新的穩定發行版本，推薦在生產環境使用。</li></ul><p>Rancher 的安裝方法有多種。在這篇教程中我們僅討論兩種方法。</p><ul><li>以單一容器的方式安裝 Rancher（內嵌 Rancher 資料庫）</li><li>以單一容器的方式安裝 Rancher（外部資料庫）</li></ul><h3 id="方法-1" tabindex="-1">方法 - 1 <a class="header-anchor" href="#方法-1" aria-label="Permalink to “方法 - 1”">​</a></h3><p>運行下列命令以單一容器的方式安裝 Rancher 服務器（內嵌資料庫）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker run -d --restart=unless-stopped -p 8080:8080 rancher/server:stable</span></span>
<span class="line"><span>$ sudo docker run -d --restart=unless-stopped -p 8080:8080 rancher/server:latest</span></span></code></pre></div><h3 id="方法-2" tabindex="-1">方法 - 2 <a class="header-anchor" href="#方法-2" aria-label="Permalink to “方法 - 2”">​</a></h3><p>你可以在啓動 Rancher 服務器時指向外部資料庫，而不是使用自帶的內部資料庫。首先創建所需的資料庫，資料庫用户為同一個。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; CREATE DATABASE IF NOT EXISTS cattle COLLATE = &#39;utf8_general_ci&#39; CHARACTER SET = &#39;utf8&#39;;</span></span>
<span class="line"><span>&gt; GRANT ALL ON cattle.* TO &#39;cattle&#39;@&#39;%&#39; IDENTIFIED BY &#39;cattle&#39;;</span></span>
<span class="line"><span>&gt; GRANT ALL ON cattle.* TO &#39;cattle&#39;@&#39;localhost&#39; IDENTIFIED BY &#39;cattle&#39;;</span></span></code></pre></div><p>運行下列命令啓動 Rancher 去連接外部資料庫。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker run -d --restart=unless-stopped -p 8080:8080 rancher/server \\</span></span>
<span class="line"><span> --db-host myhost.example.com --db-port 3306 --db-user username --db-pass password --db-name cattle</span></span></code></pre></div><p>如果你想測試 Rancher 2.0，使用下列的命令去啓動。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker run -d --restart=unless-stopped -p 80:80 -p 443:443 rancher/server:preview</span></span></code></pre></div><h3 id="通過-gui-訪問-安裝-rancher" tabindex="-1">通過 GUI 訪問 &amp; 安裝 Rancher <a class="header-anchor" href="#通過-gui-訪問-安裝-rancher" aria-label="Permalink to “通過 GUI 訪問 &amp; 安裝 Rancher”">​</a></h3><p>瀏覽器輸入 <code>http://hostname:8080</code> 或 <code>http://server_ip:8080</code> 去訪問 rancher GUI.</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-1.png" alt=""></p><h3 id="怎樣註冊主機" tabindex="-1">怎樣註冊主機 <a class="header-anchor" href="#怎樣註冊主機" aria-label="Permalink to “怎樣註冊主機”">​</a></h3><p>註冊你的主機 URL 允許它連接到 Rancher API。這是一次性設置。</p><p>接下來，點擊主菜單下面的 “Add a Host” 鏈接或者點擊主菜單上的 “INFRASTRUCTURE &gt;&gt; Add Hosts”，點擊 “Save” 按鈕。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-2.png" alt=""></p><p>默認情況下，Rancher 裏的訪問控制認證禁止了訪問，因此我們首先需要通過一些方法打開訪問控制認證，否則任何人都不能訪問 GUI。</p><p>點擊 “&gt;&gt; Admin &gt;&gt; Access Control”，輸入下列的值最後點擊 “Enable Authentication” 按鈕去打開它。在我這裏，是通過 “local authentication” 的方式打開的。</p><ul><li>“Login UserName”： 輸入你期望的登錄名</li><li>“Full Name”： 輸入你的全名</li><li>“Password”： 輸入你期望的密碼</li><li>“Confirm Password”： 再一次確認密碼</li></ul><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-3.png" alt=""></p><p>註銷然後使用新的登錄憑證重新登錄：</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-3a.png" alt=""></p><p>現在，我能看到本地認證已經被打開。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-4.png" alt=""></p><h3 id="怎樣添加主機" tabindex="-1">怎樣添加主機 <a class="header-anchor" href="#怎樣添加主機" aria-label="Permalink to “怎樣添加主機”">​</a></h3><p>註冊你的主機後，它將帶你進入下一個頁面，在那裏你能選擇不同雲服務提供商的 Linux 主機。我們將添加一個主機運行 Rancher 服務，因此選擇“custom”選項然後輸入必要的信息。</p><p>在第 4 步輸入你服務器的公有 IP，運行第 5 步列出的命令，最後點擊 “close” 按鈕。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo docker run -e CATTLE_AGENT_IP=&quot;192.168.56.2&quot;  --rm --privileged -v /var/run/docker.sock:/var/run/docker.sock -v /var/lib/rancher:/var/lib/rancher rancher/agent:v1.2.11 http://192.168.56.2:8080/v1/scripts/16A52B9BE2BAB87BB0F5:1546214400000:ODACe3sfis5V6U8E3JASL8jQ</span></span>
<span class="line"><span></span></span>
<span class="line"><span>INFO: Running Agent Registration Process, CATTLE_URL=http://192.168.56.2:8080/v1</span></span>
<span class="line"><span>INFO: Attempting to connect to: http://192.168.56.2:8080/v1</span></span>
<span class="line"><span>INFO: http://192.168.56.2:8080/v1 is accessible</span></span>
<span class="line"><span>INFO: Configured Host Registration URL info: CATTLE_URL=http://192.168.56.2:8080/v1 ENV_URL=http://192.168.56.2:8080/v1</span></span>
<span class="line"><span>INFO: Inspecting host capabilities</span></span>
<span class="line"><span>INFO: Boot2Docker: false</span></span>
<span class="line"><span>INFO: Host writable: true</span></span>
<span class="line"><span>INFO: Token: xxxxxxxx</span></span>
<span class="line"><span>INFO: Running registration</span></span>
<span class="line"><span>INFO: Printing Environment</span></span>
<span class="line"><span>INFO: ENV: CATTLE_ACCESS_KEY=9946BD1DCBCFEF3439F8</span></span>
<span class="line"><span>INFO: ENV: CATTLE_AGENT_IP=192.168.56.2</span></span>
<span class="line"><span>INFO: ENV: CATTLE_HOME=/var/lib/cattle</span></span>
<span class="line"><span>INFO: ENV: CATTLE_REGISTRATION_ACCESS_KEY=registrationToken</span></span>
<span class="line"><span>INFO: ENV: CATTLE_REGISTRATION_SECRET_KEY=xxxxxxx</span></span>
<span class="line"><span>INFO: ENV: CATTLE_SECRET_KEY=xxxxxxx</span></span>
<span class="line"><span>INFO: ENV: CATTLE_URL=http://192.168.56.2:8080/v1</span></span>
<span class="line"><span>INFO: ENV: DETECTED_CATTLE_AGENT_IP=172.17.0.1</span></span>
<span class="line"><span>INFO: ENV: RANCHER_AGENT_IMAGE=rancher/agent:v1.2.11</span></span>
<span class="line"><span>INFO: Launched Rancher Agent: e83b22afd0c023dabc62404f3e74abb1fa99b9a178b05b1728186c9bfca71e8d</span></span></code></pre></div><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-5.png" alt=""></p><p>等待幾秒鐘後新添加的主機將會出現。點擊 “Infrastructure &gt;&gt; Hosts” 頁面。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-6.png" alt=""></p><h3 id="怎樣查看容器" tabindex="-1">怎樣查看容器 <a class="header-anchor" href="#怎樣查看容器" aria-label="Permalink to “怎樣查看容器”">​</a></h3><p>只需要點擊下列位置就能列出所有容器。點擊 “Infrastructure &gt;&gt; Containers” 頁面。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-7.png" alt=""></p><h3 id="怎樣創建容器" tabindex="-1">怎樣創建容器 <a class="header-anchor" href="#怎樣創建容器" aria-label="Permalink to “怎樣創建容器”">​</a></h3><p>非常簡單，只需點擊下列位置就能創建容器。</p><p>點擊 “Infrastructure &gt;&gt; Containers &gt;&gt; Add Container” 然後輸入每個你需要的信息。為了測試，我將創建一個 <code>latest</code> 標籤的 CentOS 容器。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-8.png" alt=""></p><p>在同樣的列表位置，點擊 “ Infrastructure &gt;&gt; Containers”。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-9.png" alt=""></p><p>點擊容器名展示容器的性能信息，如 CPU、內存、網絡和存儲。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-10.png" alt=""></p><p>選擇特定容器，然後點擊最右邊的“三點”按鈕或者點擊“Actions”按鈕對容器進行管理，如停止、啓動、克隆、重啓等。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-11.png" alt=""></p><p>如果你想控制台訪問容器，只需要點擊 “Actions” 按鈕中的 “Execute Shell” 選項即可。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-12.png" alt=""></p><h3 id="怎樣從應用目錄部署容器" tabindex="-1">怎樣從應用目錄部署容器 <a class="header-anchor" href="#怎樣從應用目錄部署容器" aria-label="Permalink to “怎樣從應用目錄部署容器”">​</a></h3><p>Rancher 提供了一個應用模版目錄，讓部署變的很容易，只需要單擊一下就可以。 它維護了多數流行應用，這些應用由 Rancher 社區貢獻。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-13.png" alt=""></p><p>點擊 “Catalog &gt;&gt; All &gt;&gt; Choose the required application”，最後點擊 “Launch” 去部署。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2018/02/Install-rancher-container-management-application-in-linux-14.png" alt=""></p><hr>`,61)),e("p",null,[a[10]||(a[10]=n("via: ",-1)),s(t,{href:"https://www.2daygeek.com/rancher-a-complete-container-management-platform-for-production-environment/"},{default:i(()=>[...a[9]||(a[9]=[n("https://www.2daygeek.com/rancher-a-complete-container-management-platform-for-production-environment/",-1)])]),_:1})]),e("p",null,[a[14]||(a[14]=n("作者：",-1)),s(t,{href:"https://www.2daygeek.com/author/magesh/"},{default:i(()=>[...a[11]||(a[11]=[n("Magesh Maruthamuthu",-1)])]),_:1}),a[15]||(a[15]=n(" 譯者：",-1)),s(t,{href:"https://github.com/arrowfeng"},{default:i(()=>[...a[12]||(a[12]=[n("arrowfeng",-1)])]),_:1}),a[16]||(a[16]=n(" 校對：",-1)),s(t,{href:"https://github.com/wxy"},{default:i(()=>[...a[13]||(a[13]=[n("wxy",-1)])]),_:1})]),e("p",null,[a[19]||(a[19]=n("本文由 ",-1)),s(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[17]||(a[17]=[n("LCTT",-1)])]),_:1}),a[20]||(a[20]=n(" 原創編譯，",-1)),s(t,{href:"https://linux.cn/"},{default:i(()=>[...a[18]||(a[18]=[n("Linux中國",-1)])]),_:1}),a[21]||(a[21]=n(" 榮譽推出",-1))])])}const T=l(d,[["render",h]]);export{x as __pageData,T as default};
